fn parse_usize_with_name(s: &str, name: &str) -> Result<usize, String> {
    match s.parse::<usize>() {
        Ok(v) => Ok(v),
        Err(e) => {
            // Build error message exactly like original
            // Example: "-l, --len <integer> expected. ParseIntError { kind: InvalidDigit }\nerror: invalid digit found in string"
            // name is like "-l, --len"
            // Need to produce string that will be printed to stderr and exit 1
            // In original binary, this error was printed directly, not via clap.
            // We'll handle outside.
            Err(format!("{} <integer> expected. {:?}\nerror: {}", name, e, e))
        }
    }
}

fn main() {
    // Define clap command to get help/version and also handle allowed values for format, color, array, prefix
    let cmd = Command::new("hx")
        .about("Futuristic take on hexdump, made in Rust.")
        .version("0.7.0")
        .arg(Arg::new("cols").short('c').long("cols").value_name("columns").help("Set column length"))
        .arg(Arg::new("len").short('l').long("len").value_name("len").help("Set <len> bytes to read"))
        .arg(Arg::new("format").short('f').long("format").value_name("format").help("Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)").value_parser(["o","x","X","b"]))
        .arg(Arg::new("color").short('t').long("color").value_name("color").help("Set color tint terminal output. 0 to disable, 1 to enable").value_parser(["0","1"]))
        .arg(Arg::new("array").short('a').long("array").value_name("array_format").help("Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)").value_parser(["r","c","g","p","k","j","s","f"]))
        .arg(Arg::new("func").short('u').long("func").value_name("func_length").help("Set function wave length"))
        .arg(Arg::new("places").short('p').long("places").value_name("func_places").help("Set function wave output decimal places"))
        .arg(Arg::new("prefix").short('r').long("prefix").value_name("prefix").help("Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable").value_parser(["0","1"]))
        .arg(Arg::new("INPUTFILE").value_name("INPUTFILE").help("Pass file path as an argument, or input data may be passed via stdin"));

    let matches = cmd.clone().try_get_matches_from(std::env::args()).unwrap_or_else(|e| {
        // clap will handle help/version and also errors for invalid values, missing values, unexpected args, multiple occurrences
        e.exit()
