        io::stdin().read_to_end(&mut data).unwrap();
    }

    // If len ==0 means all, else truncate
    if len != 0 && len < data.len() {
        data.truncate(len);
    }

    // If func is set, ignore other options except places? According to earlier, -c, -f, -r, -a ignored, -l ignored, -t affects? color for func? We saw color with func had no color (func output had no escape codes even with -t 1). So color ignored for func as well? Let's test: earlier we tested func with -t 1 and it had no color (output had no escape). So color disabled for func.
    // Actually previous test: echo -n "ABC" | ./executable -t 1 -u 5 -c 3 had no color (od -c showed no escape). So for func, color is ignored.
    // So for func mode, we just generate sine wave.

    if let Some(func_len) = func_opt {
        let places = places_opt.unwrap_or(4);
        // Generate func_len values: sin(i * pi/2 / func_len) for i 0..func_len-1
        // If func_len==0, output just newline? Observed "\n"
        if func_len == 0 {
