                std::process::exit(1);
            }
        }
    } else { None };

    // func mode - ignore file, early return
    if let Some(func_len) = func_opt {
        let places = places_opt.unwrap_or(4);
        if func_len == 0 {
            println!();
            return;
        }
        let mut lines: Vec<String> = Vec::new();
        let mut current_line = String::new();
        for i in 0..func_len {
            let val = ((i as f64) * std::f64::consts::PI / 2.0 / (func_len as f64)).sin();
            let formatted = format!("{:.*},", places, val);
            current_line.push_str(&formatted);
            if (i+1) % 10 == 0 {
                lines.push(current_line);
                current_line = String::new();
            }
        }
        if !current_line.is_empty() {
            lines.push(current_line);
        }
        if func_len % 10 == 0 {
            lines.push(String::new());
        }
        for line in lines {
            println!("{}", line);
        }
        return;
    }

    let format = matches.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("x");
    let color_opt = matches.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("");
    let has_color_arg = matches.contains_id("color");
    let array_opt = matches.get_one::<String>("array").map(|s| s.chars().next().unwrap());
    let prefix_opt_str = matches.get_one::<String>("prefix");
    let inputfile = matches.get_one::<String>("INPUTFILE").cloned();

    let color_explicit: Option<u8> = if has_color_arg { Some(color_opt.parse::<u8>().unwrap()) } else { None };
    let prefix_explicit: Option<u8> = if let Some(s) = prefix_opt_str { Some(s.parse::<u8>().unwrap()) } else { None };

    let color_enabled = if let Some(c) = color_explicit { c == 1 } else {
        if std::env::var("NO_COLOR").is_ok() { false } else {
            use std::io::IsTerminal;
            std::io::stdout().is_terminal()
        }
    };

    let mut data: Vec<u8> = Vec::new();
    if let Some(path) = inputfile {
        match fs::read(&path) {
            Ok(b) => data = b,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        io::stdin().read_to_end(&mut data).unwrap();
    }

    if len != 0 && len < data.len() {
        data.truncate(len);
    }

    if let Some(arr_fmt) = array_opt {
        let cols_eff = if cols == 0 { 1 } else { cols };
        let n = data.len();
        let (header, footer) = match arr_fmt {
            'r' => (format!("let ARRAY: [u8; {}] = [", n), "];".to_string()),
            'c' => (format!("unsigned char ARRAY[{}] = {{", n), "};".to_string()),
            'g' => (format!("a := [{}]byte{{", n), "}".to_string()),
            'p' => (format!("a = ["), "]".to_string()),
            'k' => (format!("val a = byteArrayOf("), ")".to_string()),
            'j' => (format!("byte[] a = new byte[]{{"), "};".to_string()),
            's' => (format!("let a: [UInt8] = ["), "]".to_string()),
            'f' => (format!("let a = [|"), "|]".to_string()),
            _ => unreachable!(),
        };
        let indent = "    ";
        let sep = if arr_fmt == 'f' { "; " } else { ", " };
        println!("{}", header);
        if n == 0 {
            println!("{}", indent);
            println!("{}", footer);
            return;
        }
        let need_blank = n % cols_eff == 0;
        let is_g = arr_fmt == 'g';
        let mut chunk_start = 0;
        while chunk_start < n {
            let chunk_end = std::cmp::min(chunk_start + cols_eff, n);
            let is_last_chunk = chunk_end == n;
            let mut line = String::from(indent);
            for (idx, b) in data[chunk_start..chunk_end].iter().enumerate() {
                let token = if arr_fmt == 'f' {
                    format!("0x{:02x}uy", b)
                } else {
                    format!("0x{:02x}", b)
                };
                line.push_str(&token);
                if idx + 1 < chunk_end - chunk_start {
                    line.push_str(sep);
                } else {
                    if !is_last_chunk {
                        line.push_str(sep);
                    } else {
                        if is_g {
                            line.push_str(sep);
                        }
                    }
                }
            }
            println!("{}", line);
            chunk_start = chunk_end;
        }
        if need_blank {
            println!("{}", indent);
        }
        println!("{}", footer);
        return;
    }

    let prefix_enabled = if let Some(p) = prefix_explicit { p == 1 } else { true };
    let cols_eff = if cols == 0 { 1 } else { cols };
    let total = data.len();
    if total == 0 {
        let pad_spaces = if cols == 0 { 0 } else { cols_eff * 5 };
        println!("0x{:06x}: {:pad$}", 0, "", pad = pad_spaces);
        println!("   bytes: {}", total);
        return;
    }
    let mut offset = 0usize;
    while offset < total {
        let remaining = total - offset;
        let count = std::cmp::min(cols_eff, remaining);
        let mut hex_part = String::new();
        for i in 0..count {
            let b = data[offset + i];
            let token = match format {
                "x" => if prefix_enabled { format!("0x{:02x}", b) } else { format!("{:02x}", b) },
                "X" => if prefix_enabled { format!("0x{:02X}", b) } else { format!("{:02X}", b) },
                "o" => if prefix_enabled { format!("0o{:04o}", b) } else { format!("{:04o}", b) },
                "b" => if prefix_enabled { format!("0b{:08b}", b) } else { format!("{:08b}", b) },
                _ => unreachable!(),
            };
            let token_colored = if color_enabled {
                let col = if b == 0 { 22 } else { b as usize };
                format!("\x1b[38;5;{}m{}\x1b[0m", col, token)
            } else {
                token
            };
            hex_part.push_str(&token_colored);
            hex_part.push(' ');
        }
        if count < cols_eff {
            let missing = cols_eff - count;
            hex_part.push_str(&" ".repeat(missing * 5));
        }
        let mut ascii_part = String::new();
        for i in 0..count {
            let b = data[offset + i];
            let ch = if b >= 32 && b <= 126 { b as char } else { '.' };
            if color_enabled {
                let col = if b == 0 { 22 } else { b as usize };
                ascii_part.push_str(&format!("\x1b[38;5;{}m{}\x1b[0m", col, ch));
            } else {
                ascii_part.push(ch);
            }
        }
        println!("0x{:06x}: {}{}", offset, hex_part, ascii_part);
        offset += count;
    }
    if total % cols_eff == 0 {
        let pad_spaces = if cols == 0 { 0 } else { cols_eff * 5 };
        println!("0x{:06x}: {:pad$}", total, "", pad = pad_spaces);
    }
    println!("   bytes: {}", total);
}
