# We have executable_new which is new binary but named executable_new, so usage says executable_new not executable. To make usage match, we can create a symlink or copy with same name in another directory and run from there? The binary's name in usage is determined by args[0] as passed. If we invoke "./executable_new", it will show "executable_new". If we invoke "./executable" (original), it shows "executable". To make new binary show "executable" in usage, we need to invoke it via a path that ends with "executable". Since we cannot overwrite ./executable, we can create a temporary directory, copy new binary there as "executable", and run it from there.

mkdir -p /tmp/testbin
cp ./target/debug/hx /tmp/testbin/executable
chmod +x /tmp/testbin/executable
/tmp/testbin/executable --help 2>&1 | head -n 5
./executable --help 2>&1 | head -n 5

# Now test comparing /tmp/testbin/executable vs ./executable (original)
python3 <<'PY'
import subprocess

def run_orig(data, args):
    p=subprocess.run(["./executable"]+args, input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout, p.stderr, p.returncode

def run_new(data, args):
    p=subprocess.run(["/tmp/testbin/executable"]+args, input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout, p.stderr, p.returncode

def test_case(data, args):
    o, oe, oc = run_orig(data, args)
    n, ne, nc = run_new(data, args)
    if o!=n or oe!=ne or oc!=nc:
        print(f"MISMATCH for data={data!r} args={args}")
        print(f"ORIG out: {o!r} err: {oe!r} code {oc}")
        print(f"NEW  out: {n!r} err: {ne!r} code {nc}")
        return False
    return True

ok=True
for cols in [0,1,2,3,5,10]:
    for fmt in ["x","X","o","b"]:
        for pref in ["0","1"]:
            for data in [b"", b"A", b"AB", b"ABC", b"0123456789"]:
                args=["-t","0","-c",str(cols),"-f",fmt,"-r",pref]
                if not test_case(data, args):
                    ok=False

for arr in ["r","c","g","p","k","j","s","f"]:
    for cols in [0,1,2,3,10]:
        for data in [b"", b"A", b"AB", b"ABC", b"ABCDEFGHI"]:
            if not test_case(data, ["-t","0","-a",arr,"-c",str(cols)]):
                ok=False

for func_len in [0,1,2,3,10,11,20]:
    for places in [0,2,4]:
        if not test_case(b"", ["-t","0","-u",str(func_len),"-p",str(places)]):
            ok=False
    if not test_case(b"", ["-t","0","-u",str(func_len)]):
        ok=False

for args in [["--cols"], ["--unknown"], ["-z"], ["-f","z"], ["-a","z"], ["-t","2"], ["--help"], ["-h"], ["--version"], ["-V"], ["notfound"], ["-t","0","notfound"], ["-a","r","notfound"], ["-t","0","-u","5","notfound"], ["-t","0","-a","r","-u","3","notfound"]]:
    o, oe, oc = run_orig(b"A", args)
    n, ne, nc = run_new(b"A", args)
    if o!=n or oe!=ne or oc!=nc:
        print(f"MISMATCH err case args={args}")
        print(f"ORIG {o!r} {oe!r} {oc}")
        print(f"NEW {n!r} {ne!r} {nc}")
        ok=False

for args in [["-l","abc"], ["-c","abc"], ["-u","abc"], ["-p","abc","-u","5"], ["-l",""], ["-c",""], ["-u",""], ["-p","","-u","5"], ["-l","999999999999999999999"]]:
    o, oe, oc = run_orig(b"A", args)
    n, ne, nc = run_new(b"A", args)
    if o!=n or oe!=ne or oc!=nc:
        print(f"INT ERR MISMATCH args={args}")
        print(f"ORIG out {o!r} err {oe!r} code {oc}")
        print(f"NEW  out {n!r} err {ne!r} code {nc}")
        ok=False

print("done ok", ok)
PY
